-- Migration: 080_evaluation_annual_release_and_reward_payment.sql
-- 年度评价正式发布、公示、锁定和奖励支付凭证闭环。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研评价年度批次" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "评价年度" integer NOT NULL,
    "批次名称" varchar(200) NOT NULL DEFAULT '年度科研绩效评价',
    "版本号" integer NOT NULL DEFAULT 1,
    "状态" varchar(20) NOT NULL DEFAULT '草稿',
    "公示开始日期" date,
    "公示结束日期" date,
    "公示说明" varchar(4000),
    "发布人编号" integer,
    "发布时间" timestamp without time zone,
    "锁定人编号" integer,
    "锁定时间" timestamp without time zone,
    "结算人编号" integer,
    "结算时间" timestamp without time zone,
    "备注" varchar(2000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研评价年度批次" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研评价年度批次_年度版本" UNIQUE ("评价年度", "版本号"),
    CONSTRAINT "ck_科研评价年度批次_年度" CHECK ("评价年度" BETWEEN 2000 AND 2200),
    CONSTRAINT "ck_科研评价年度批次_状态" CHECK ("状态" IN ('草稿','公示中','已发布','已锁定','已结算','作废')),
    CONSTRAINT "ck_科研评价年度批次_公示日期" CHECK ("公示结束日期" IS NULL OR "公示开始日期" IS NULL OR "公示结束日期" >= "公示开始日期")
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_科研评价年度批次_当前年度" ON "科研评价年度批次" ("评价年度") WHERE "状态" <> '作废';
CREATE INDEX IF NOT EXISTS "ix_科研评价年度批次_状态" ON "科研评价年度批次" ("状态", "评价年度" DESC);

ALTER TABLE "科研评价结果" ADD COLUMN IF NOT EXISTS "年度批次编号" bigint;
ALTER TABLE "科研评价结果" ADD COLUMN IF NOT EXISTS "公示状态" varchar(20) NOT NULL DEFAULT '未纳入';
ALTER TABLE "科研评价结果" ADD COLUMN IF NOT EXISTS "公示时间" timestamp without time zone;
ALTER TABLE "科研评价结果" ADD COLUMN IF NOT EXISTS "锁定时间" timestamp without time zone;
ALTER TABLE "科研评价结果" DROP CONSTRAINT IF EXISTS "fk_科研评价结果_年度批次";
ALTER TABLE "科研评价结果" ADD CONSTRAINT "fk_科研评价结果_年度批次" FOREIGN KEY ("年度批次编号") REFERENCES "科研评价年度批次" ("编号");
ALTER TABLE "科研评价结果" DROP CONSTRAINT IF EXISTS "ck_科研评价结果_公示状态";
ALTER TABLE "科研评价结果" ADD CONSTRAINT "ck_科研评价结果_公示状态" CHECK ("公示状态" IN ('未纳入','公示中','已公示','已撤回'));
CREATE INDEX IF NOT EXISTS "ix_科研评价结果_年度批次" ON "科研评价结果" ("年度批次编号", "公示状态", "评价年度");

ALTER TABLE "科研评价奖励" ADD COLUMN IF NOT EXISTS "发放批次号" varchar(100);
ALTER TABLE "科研评价奖励" ADD COLUMN IF NOT EXISTS "支付状态" varchar(20) NOT NULL DEFAULT '待支付';
ALTER TABLE "科研评价奖励" ADD COLUMN IF NOT EXISTS "支付凭证号" varchar(100);
ALTER TABLE "科研评价奖励" ADD COLUMN IF NOT EXISTS "支付时间" timestamp without time zone;
ALTER TABLE "科研评价奖励" DROP CONSTRAINT IF EXISTS "ck_科研评价奖励_支付状态";
ALTER TABLE "科研评价奖励" ADD CONSTRAINT "ck_科研评价奖励_支付状态" CHECK ("支付状态" IN ('待支付','已支付','支付失败','不予支付'));
CREATE INDEX IF NOT EXISTS "ix_科研评价奖励_支付" ON "科研评价奖励" ("支付状态", "支付时间", "评价结果编号");
UPDATE "科研评价奖励" SET "支付状态" = CASE WHEN "状态" = '已发放' THEN '已支付' WHEN "状态" = '不予发放' THEN '不予支付' ELSE '待支付' END WHERE "支付状态" = '待支付';

UPDATE "系统迁移版本"
   SET "版本" = 80,
       "脚本" = '080_evaluation_annual_release_and_reward_payment.sql',
       "检查摘要" = '增加年度评价公示发布锁定批次和奖励支付状态、支付凭证闭环',
       "应用时间" = CURRENT_TIMESTAMP
 WHERE "编号" = 1;
COMMIT;
